SELECT * FROM t_spd_stock WHERE del_flag = #{delFlag}

    AND warehouse_id = #{query.warehouseId}


    AND material_id = #{query.materialId}


    AND material_name LIKE CONCAT('%', #{query.materialName}, '%')


    AND batch_no LIKE CONCAT('%', #{query.batchNo}, '%')

ORDER BY create_time DESC
